/**
 * Release Active Approval Request
 *
 * Creates a distinct append-only ACTIVE approval after a canary monitoring checkpoint was persisted in a prior transaction. The request's canary monitoring and evidence artifact/hash fields must exactly match that immutable checkpoint; the ACTIVE approval transaction cannot create or alter them. Neither approver may be the bound Prompt Version author. The ACTIVE manifest, approval artifact, and approval artifact hash must each differ from the CANARY approval.
 */
export type ReleaseActiveApprovalRequestV1 = {
    decision_manifest_sha256: string;
    primary_approver_principal_id: string;
    primary_approver_role: 'APPROVER';
    second_approver_principal_id: string;
    second_approver_role: 'OWNER';
    approval_artifact_id: string;
    approval_sha256: string;
    signed_at: string;
    canary_evidence_artifact_id: string;
    canary_evidence_sha256: string;
    canary_monitoring_artifact_id: string;
    canary_monitoring_sha256: string;
};

